   102	static void FDBRealloc(FuzzDataBuffer *FDB, size_t size) {
   103	    size_t needed = size + FF_INPUT_BUFFER_PADDING_SIZE;
   104	    av_assert0(needed > size);
   105	    if (needed > FDB->size_) {
